import pandas as pd, json
df = pd.read_csv('data.csv')
visits = pd.read_csv('visits_to_predict.csv')
# ensure date column exists in visits; assume same column name 'date'
if 'date' not in visits.columns:
    # try alternative name
    if 'timestamp' in visits.columns:
        visits = visits.rename(columns={'timestamp':'date'})
    else:
        raise KeyError('date column missing in visits_to_predict.csv')
# compute predictions
pred = {}
for _, v in visits.iterrows():
    pid = v['period_id']
    vdate = pd.to_datetime(v['date'])
    past = df[(df['period_id']==pid) & (pd.to_datetime(df['date'])<vdate)]
    if past.empty:
        # fallback overall mean per band
        for b in df['band'].unique():
            pred.setdefault(pid, {})[b] = df[df['band']==b]['y'].mean()
    else:
        for b in past['band'].unique():
            pred.setdefault(pid, {})[b] = past[past['band']==b]['y'].mean()
# ensure every band present for each visit
all_bands = df['band'].unique()
for pid in pred:
    for b in all_bands:
        pred[pid].setdefault(b, df[df['band']==b]['y'].mean())
out = {
    "prediction": pred,
    "rationale": "For each visit, predicted each band's value as the mean of that band's past observations for the same parcel (same period_id) before the visit date; if no past data, used overall band mean."
}
with open('answer.json','w') as f:
    json.dump(out, f, indent=2)
print(json.dumps(out, indent=2))
