import csv, json, os

# Load data.csv and compute mean per band
band_vals = {}
with open('data.csv', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        band = row['band']
        val = float(row['y'])
        band_vals.setdefault(band, []).append(val)

means = {b: sum(v)/len(v) for b, v in band_vals.items()}

# Load visits_to_predict.csv
visits = []
with open('visits_to_predict.csv', newline='') as f:
    reader = csv.DictReader(f)
    for row in reader:
        visits.append(row)

# Build prediction dict
prediction = {}
for v in visits:
    pid = v['period_id']
    prediction[pid] = {b: means[b] for b in means}

answer = {
    "prediction": prediction,
    "rationale": "Used simple historical mean of each band from data.csv as forecast for each period_id in visits_to_predict.csv."
}

with open('answer.json', 'w') as f:
    json.dump(answer, f, indent=2)

print(json.dumps(answer, indent=2))
